/**
 * Test 4: Cumulative Results Updates on Day Navigation (BUG-20251216)
 * 
 * Reproduces the bug where Cumulative Results section remains blank when navigating
 * between days using Previous/Next buttons. The section should update automatically
 * without requiring strategy switching as a workaround.
 * 
 * Expected behavior:
 * - Navigating to a day should populate Cumulative Results if trades exist
 * - Navigating to previous/next day should update Cumulative Results section
 * - No strategy switching should be required for data to appear
 */
test("cumulative results section updates when navigating between days without strategy switching", {
  annotation: {
    type: "description",
    description: "Reproduces BUG-20251216: Cumulative Results section should update automatically when navigating between days using Previous/Next buttons, without requiring strategy switching as a workaround. This test verifies that day navigation triggers strategy results to be saved and displayed correctly."
  }
}, async ({ page }) => {
  // Clear localStorage to start fresh
  await page.goto("/");
  await page.evaluate(() => {
    localStorage.removeItem("rockcap:strategyResults");
  });
  await page.reload();
  await waitForAlgoTrades(page);

  // Step 1: Navigate to first day and verify Cumulative Results section
  // Expected: Section should show data or appropriate message (not blank)
  const section = page.getByTestId("strategy-results-section");
  await expect(section).toBeVisible();

  // Check if we have bars (data) or the "Navigate days to collect data" message
  const bars = page.getByTestId("strategy-results-bar");
  const barCount = await bars.count();
  const cumulativeValue = await page.getByTestId("strategy-results-cumulative-value").innerText();

  // If we have trades on this day, we should see data; otherwise we might see placeholder
  const hasData = barCount > 0 || cumulativeValue !== "—";

  // Step 2: Navigate to previous day
  // Expected: Cumulative Results should update (either show new data or update existing)
  const prevBtn = page.getByTestId("prev-day");
  if (await prevBtn.isEnabled()) {
    await prevBtn.click();
    await waitForBacktestLoaded(page);
    await page.waitForTimeout(2000); // Wait for algo generation and results save

    // Verify section is still visible and has updated
    await expect(section).toBeVisible();

    // After navigation, we should have data if trades exist
    // The bug manifests as: section appears blank even when trades exist
    const barsAfterNav1 = page.getByTestId("strategy-results-bar");
    const barCountAfterNav1 = await barsAfterNav1.count();
    const cumulativeValueAfterNav1 = await page.getByTestId("strategy-results-cumulative-value").innerText();

    // If we had data before, we should still have data (or more)
    // If we didn't have data, we might have data now if this day has trades
    const hasDataAfterNav1 = barCountAfterNav1 > 0 || cumulativeValueAfterNav1 !== "—";

    // Step 3: Navigate to previous day again
    // Expected: Cumulative Results should continue to update
    const prevBtn2 = page.getByTestId("prev-day");
    if (await prevBtn2.isEnabled()) {
      await prevBtn2.click();
      await waitForBacktestLoaded(page);
      await page.waitForTimeout(2000); // Wait for algo generation and results save

      // Verify section is still visible
      await expect(section).toBeVisible();

      const barsAfterNav2 = page.getByTestId("strategy-results-bar");
      const barCountAfterNav2 = await barsAfterNav2.count();
      const cumulativeValueAfterNav2 = await page.getByTestId("strategy-results-cumulative-value").innerText();

      // After 2 navigations, if we've visited days with trades, we should have data
      // The bug: section remains blank even after navigating to days with trades
      const hasDataAfterNav2 = barCountAfterNav2 > 0 || cumulativeValueAfterNav2 !== "—";

      // Assertion: If we've navigated and there are trades, we should see data
      // This will fail with the current bug where section stays blank
      const entryText = await page.getByTestId("entry-input").innerText();
      const hasTrades = entryText !== "No trade" && entryText !== "–";

      if (hasTrades) {
        // If this day has trades, Cumulative Results should show data
        expect(
          hasDataAfterNav2 || barCountAfterNav2 > 0,
          `BUG-20251216: Cumulative Results section should show data after navigating to a day with trades. ` +
          `Bar count: ${barCountAfterNav2}, Cumulative value: "${cumulativeValueAfterNav2}", Entry: "${entryText}"`
        ).toBe(true);
      }
    }
  } else {
    // If prev button is disabled, try next button
    const nextBtn = page.getByTestId("next-day");
    if (await nextBtn.isEnabled()) {
      await nextBtn.click();
      await waitForBacktestLoaded(page);
      await page.waitForTimeout(2000);

      await expect(section).toBeVisible();
      const barsAfterNav = page.getByTestId("strategy-results-bar");
      const barCountAfterNav = await barsAfterNav.count();
      const cumulativeValueAfterNav = await page.getByTestId("strategy-results-cumulative-value").innerText();

      const entryText = await page.getByTestId("entry-input").innerText();
      const hasTrades = entryText !== "No trade" && entryText !== "–";

      if (hasTrades) {
        expect(
          barCountAfterNav > 0 || cumulativeValueAfterNav !== "—",
          `BUG-20251216: Cumulative Results section should show data after navigating to a day with trades. ` +
          `Bar count: ${barCountAfterNav}, Cumulative value: "${cumulativeValueAfterNav}", Entry: "${entryText}"`
        ).toBe(true);
      }
    }
  }
});

