args.new_string:
/** All strategy results (one entry per day) - raw array */
const strategyResults = snap.strategyResults as StrategyDayResult[];

/** Strategy results sorted by date (newest first) */
// FIX BUG-20251216: Use snapshot directly for reactivity instead of calling function that reads from backtestState
const strategyResultsSorted = [...strategyResults].sort((a, b) => 
  new Date(b.date).getTime() - new Date(a.date).getTime()
);

/** Aggregate statistics: total P&L, trade count, date range */
// FIX BUG-20251216: Use snapshot directly for reactivity instead of calling function that reads from backtestState
const strategyResultsStats = (() => {
  if (strategyResults.length === 0) {
    return { total: 0, count: 0, earliest: null, latest: null };
  }
  const total = strategyResults.reduce((sum, r) => sum + r.pnl, 0);
  const totalTradeCount = strategyResults.reduce((sum, r) => sum + (r.tradeCount ?? 0), 0);
  const sorted = [...strategyResults].sort((a, b) => 
    new Date(a.date).getTime() - new Date(b.date).getTime()
  );
  return {
    total,
    count: totalTradeCount,
    earliest: sorted[0].date,
    latest: sorted[sorted.length - 1].date,
  };
})();

