/**
 * Test 4: URL Parameters Load Correctly on Initial Page Load (BUG-20251216)
 * 
 * Verifies that when navigating to a URL with strategy and steppedSL parameters,
 * they are properly loaded and applied on initial page load, not just after navigation.
 * 
 * Expected behavior:
 * - Strategy from URL param should be selected in dropdown
 * - Stepped SL config from URL param should be visible (for strategy12.10.1)
 * - Cumulative Results section should populate on initial load
 * - No navigation should be required for params to apply
 */
test("URL parameters load correctly on initial page load", {
  annotation: {
    type: "description",
    description: "Reproduces BUG-20251216: URL parameters (strategy, steppedSL) should load correctly on initial page load. Strategy dropdown should show the URL strategy, stepped SL config should be visible for strategy12.10.1, and Cumulative Results should populate without requiring navigation."
  }
}, async ({ page }) => {
  // Clear localStorage to start fresh
  await page.goto("/");
  await page.evaluate(() => {
    localStorage.clear();
  });

  // Step 1: Navigate to URL with strategy and steppedSL parameters
  // Using strategy12.10.1 which supports stepped SL config
  const steppedSLConfig = JSON.stringify({ "20": 2, "25": 10, "30": 10, "40": 20 });
  const encodedSteppedSL = encodeURIComponent(steppedSLConfig);
  const testUrl = `/backtest/2025-12-03?strategy=strategy12.10.1&pt=20&sl=10&trg=8&candleType=1s&cutoffTime=09%3A45&steppedSL=${encodedSteppedSL}`;

  await page.goto(testUrl);
  await waitForBacktestLoaded(page);
  await waitForAlgoTrades(page);

  // Step 2: Verify strategy dropdown shows the URL strategy
  // Expected: Dropdown should show "strategy12.10.1" as selected
  const strategySelect = page.getByTestId("strategy-select");
  await expect(strategySelect).toHaveValue("strategy12.10.1");

  // Step 3: Verify stepped SL config input is visible and populated
  // Expected: For strategy12.10.1, stepped SL config input should be visible with the URL value
  // The input should only show for certain strategies (strategy12.8.2 or strategy12.10.1)
  const steppedSLInput = page.locator('input[placeholder*="20.*2"]').or(page.locator('input[placeholder*="stepped"]'));
  // Check if the input exists (it should for strategy12.10.1)
  const inputExists = await steppedSLInput.count() > 0;
  if (inputExists) {
    const inputValue = await steppedSLInput.inputValue();
    const parsed = JSON.parse(inputValue);
    expect(
      parsed,
      `Stepped SL config from URL should be loaded. Expected something like {"20": 2, ...}, got: ${inputValue}`
    ).toMatchObject({ "20": 2 });
  }

  // Step 4: Verify Cumulative Results section populates on initial load
  // Expected: Section should show data, not be blank
  const section = page.getByTestId("strategy-results-section");
  await expect(section).toBeVisible();

  const cumulativeValue = await page.getByTestId("strategy-results-cumulative-value").innerText();
  const bars = page.getByTestId("strategy-results-bar");
  const barCount = await bars.count();

  // If we have trades, we should see data (either bars or cumulative value)
  const entryText = await page.getByTestId("entry-input").innerText();
  const hasTrades = entryText !== "No trade" && entryText !== "–";

  if (hasTrades) {
    // Should have either bars or a cumulative value (not blank)
    const hasData = barCount > 0 || cumulativeValue !== "—";
    expect(
      hasData,
      `BUG-20251216: Cumulative Results should populate on initial load with URL params. ` +
      `Bar count: ${barCount}, Cumulative value: "${cumulativeValue}", Entry: "${entryText}"`
    ).toBe(true);
  }

  // Step 5: Verify no navigation is required - data should be there immediately
  // (Already verified above, but this makes the test intent clear)
});
